#include <stdio.h>

#define MAX 505

int main(void) {
    int n, m;
    char grid[MAX][MAX];
    int queue[MAX * MAX];
    int head = 0, tail = 0;

    if (scanf("%d %d", &n, &m) != 2) return 0;

    for (int r = 0; r < n; r++)
        scanf("%s", grid[r]);

    for (int r = 0; r < n; r++) {
        for (int c = 0; c < m; c++) {
            if (grid[r][c] == 'o')
                queue[tail++] = r * m + c;
        }
    }

    while (head < tail) {
        int pos = queue[head++];
        int r = pos / m;
        int c = pos % m;

        if (r + 1 < n && grid[r + 1][c] == '.') {
            grid[r + 1][c] = 'o';
            queue[tail++] = (r + 1) * m + c;
        }

        if (r + 1 < n && grid[r + 1][c] == '#') {
            for (int dc = -1; dc <= 1; dc += 2) {
                int nc = c + dc;
                if (nc >= 0 && nc < m && grid[r][nc] == '.') {
                    grid[r][nc] = 'o';
                    queue[tail++] = r * m + nc;
                }
            }
        }
    }

    for (int r = 0; r < n; r++)
        printf("%s\n", grid[r]);

    return 0;
}
